{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are we minimizing the number of containers used, maximizing the total weight (or value) of goods shipped, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do we have to ship all available goods (all 120 A, 90 B, 300 C, 90 D, 120 E), or is it acceptable to leave some goods unshipped as long as the containers we do use satisfy the rules?"
  ],
  "rationale": "The response asks a single clarification question regarding whether all goods must be shipped or if partial shipping is allowed."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available to us unlimited (we can use as many as needed), or is there a fixed fleet size that we must pack within?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability of containers, presenting a binary choice between unlimited and fixed capacity."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single unit of a goods type be split across multiple containers, or must each unit be loaded whole into exactly one container?"
  ],
  "rationale": "The response asks for a single policy choice regarding unit splitting, which constitutes one independent clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you say \"at least 12 units of type D\" per container, does that mean 12 whole units of D (so D must be loaded in integer units), or is it fine to treat the 12 as a weight/quantity threshold that can be met with fractional units?"
  ],
  "rationale": "The response asks a single clarification question regarding the interpretation of the unit constraint for type D."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a container contains any type A, it must contain at least one type C — does \"at least one\" mean at least 1 whole unit of C, or at least 1 ton of C?"
  ],
  "rationale": "The response asks a single clarification question regarding the unit of measurement for the constraint on type C."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the \"at least 18 tons\" minimum weight per used container a strict lower bound that must be met exactly (i.e., the container's total weight must be ≥ 18 tons), or is it a target that can be slightly violated?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the strictness of the weight constraint."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods quantities (120 A, 90 B, 300 C, 90 D, 120 E) hard upper limits that must not be exceeded, or are they the exact amounts that must all be shipped?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice between two interpretations of the quantity constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since we're minimizing the number of containers and goods are upper limits (not required to ship all), is it acceptable to ship zero goods (use zero containers) as a valid solution, or must at least one container be used?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding whether zero containers is a valid solution."
}

